// ===== Level Hunter — Auto-post carousel to Instagram + Facebook =====
// Config-оос: graphVersion, igUserId, pageId, accessToken, manifestUrl
const cfg = $input.first().json;
const G = `https://graph.facebook.com/${cfg.graphVersion}`;
const token = cfg.accessToken;
const igUser = cfg.igUserId;
const pageId = cfg.pageId;

const http = async (method, path, params) =>
  await this.helpers.httpRequest({
    method,
    url: `${G}/${path}`,
    qs: Object.assign({}, params, { access_token: token }),
    json: true,
  });

// 1) manifest татах
const manifest = await this.helpers.httpRequest({ method: 'GET', url: cfg.manifestUrl, json: true });

// 2) өнөөдрийн огноо (Asia/Ulaanbaatar = UTC+8)
const ub = new Date(Date.now() + 8 * 3600 * 1000);
const today = ub.toISOString().slice(0, 10);

// 3) өнөөдрийн queued пост
const post = (manifest.posts || []).find(p => p.date === today && p.status !== 'posted');
if (!post) {
  return [{ json: { skipped: true, today, reason: 'Өнөөдөр тавих пост алга' } }];
}

const out = { id: post.id, title: post.title, date: today, ig: null, fb: null };

// ---------- Instagram carousel (3 алхам) ----------
if (post.ig) {
  const childIds = [];
  for (const url of post.slides) {
    const c = await http('POST', `${igUser}/media`, { image_url: url, is_carousel_item: true });
    childIds.push(c.id);
  }
  const parent = await http('POST', `${igUser}/media`, {
    media_type: 'CAROUSEL',
    children: childIds.join(','),
    caption: post.caption,
  });
  // container бэлэн болтол хүлээх
  for (let i = 0; i < 20; i++) {
    const s = await http('GET', `${parent.id}`, { fields: 'status_code' });
    if (s.status_code === 'FINISHED') break;
    if (s.status_code === 'ERROR') throw new Error('IG container ERROR: ' + parent.id);
    await new Promise(r => setTimeout(r, 2000));
  }
  const pub = await http('POST', `${igUser}/media_publish`, { creation_id: parent.id });
  out.ig = pub.id;
}

// ---------- Facebook олон зурган пост ----------
if (post.fb) {
  const media = [];
  for (const url of post.slides) {
    const ph = await http('POST', `${pageId}/photos`, { url, published: false });
    media.push({ media_fbid: ph.id });
  }
  const feed = await http('POST', `${pageId}/feed`, {
    message: post.caption,
    attached_media: JSON.stringify(media),
  });
  out.fb = feed.id;
}

return [{ json: out }];
